                () -> DoorLockMachine.next(DoorLockMachine.LockState.LOCKED, DoorLockMachine.LockEvent.UNLOCK));
        checkCall("pushing a locked door does nothing", DoorLockMachine.LockState.LOCKED,
                () -> DoorLockMachine.next(DoorLockMachine.LockState.LOCKED, DoorLockMachine.LockEvent.PUSH));
        checkCall("pushing an unlocked door opens it", DoorLockMachine.LockState.OPEN,
