import java.util.EnumMap;
import java.util.Map;

/**
 * TASK: Complete DoorLockMachine. The nested LockState and LockEvent enums are
 * provided -- do not edit them.
 *
 * Instead of a switch, the machine is driven by a table that maps each state
 * to the events it understands:
 *
 *   LOCKED   + UNLOCK -> UNLOCKED
 *   UNLOCKED + LOCK   -> LOCKED
 *   UNLOCKED + PUSH   -> OPEN
 *   OPEN     + CLOSE  -> UNLOCKED
 *
 * Any other combination is ignored: the state stays as it was.
 *
 * - buildTable() fills the outer EnumMap so that every state that understands
 *   at least one event maps to an inner EnumMap of event -> new state. States
 *   with no transitions are simply absent.
 * - next(state, event) looks the move up in TABLE and returns the new state,
 *   or the unchanged state when the move is not in the table.
 * - run(start, events) applies every event in turn and returns the final state.
 * - countIgnored(start, events) applies every event in turn and counts how many
 *   of them left the state unchanged.
 *
 * Example: run(LOCKED, UNLOCK, PUSH, CLOSE, LOCK) -> LOCKED
 */
public class DoorLockMachine {

    public enum LockState { LOCKED, UNLOCKED, OPEN }

    public enum LockEvent { UNLOCK, LOCK, PUSH, CLOSE }

    private static final Map<LockState, Map<LockEvent, LockState>> TABLE = buildTable();

    static Map<LockState, Map<LockEvent, LockState>> buildTable() {
        Map<LockState, Map<LockEvent, LockState>> table = new EnumMap<>(LockState.class);

        Map<LockEvent, LockState> fromLocked = new EnumMap<>(LockEvent.class);
        fromLocked.put(LockEvent.UNLOCK, LockState.UNLOCKED);
        table.put(LockState.LOCKED, fromLocked);

        Map<LockEvent, LockState> fromUnlocked = new EnumMap<>(LockEvent.class);
        fromUnlocked.put(LockEvent.LOCK, LockState.LOCKED);
        fromUnlocked.put(LockEvent.PUSH, LockState.OPEN);
        table.put(LockState.UNLOCKED, fromUnlocked);

        Map<LockEvent, LockState> fromOpen = new EnumMap<>(LockEvent.class);
        fromOpen.put(LockEvent.CLOSE, LockState.UNLOCKED);
        table.put(LockState.OPEN, fromOpen);

        return table;
    }

    public static LockState next(LockState state, LockEvent event) {
        Map<LockEvent, LockState> row = TABLE.get(state);
        if (row == null) {
            return state;
        }
        LockState target = row.get(event);
        return (target == null) ? state : target;
    }

    public static LockState run(LockState start, LockEvent... events) {
        LockState state = start;
        for (LockEvent event : events) {
            state = next(state, event);
        }
        return state;
    }

    public static int countIgnored(LockState start, LockEvent... events) {
        int ignored = 0;
        LockState state = start;
        for (LockEvent event : events) {
            LockState after = next(state, event);
            if (after == state) {
                ignored++;
            }
            state = after;
        }
        return ignored;
    }
}
